    }
    b = 0; zz=0;
    if (qhat) {
      for (i=0; i<yd; i++) {
        zz = qhat * hd(&y,i);
        u = hd(&x,i+j);
        u-=b;
        if (u<0) {
          b=1; u+=HLMAX+1;
        }
        else
